import unittest
from unittest.mock import patch, Mock
import requests
from bs4 import BeautifulSoup
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
import datetime
from webscrapper import extract_news

class Test_WebscrapperExtractNews(unittest.TestCase):

    @patch('webscrapper.requests.get')
    def test_successful_news_extraction(self, mock_get):
        # Arrange
        mock_html = """
        <html>
            <body>
                <table>
                    <tr><td class="title" valign=""><a href="link1">News Story 1</a></td></tr>
                    <tr><td class="title" valign=""><a href="link2">News Story 2</a></td></tr>
                </table>
            </body>
        </html>
        """
        mock_get.return_value = Mock(content=mock_html)

        # Act
        result = extract_news('http://mockurl.com')

        # Assert
        expected_output = '<b>HN Top Stories:</b>\n<br>--------------------------------------------------<br>1 :: News Story 1\n<br>2 :: News Story 2\n<br>'
        self.assertEqual(result, expected_output)

    @patch('webscrapper.requests.get')
    def test_empty_news_list(self, mock_get):
        # Arrange
        mock_html = "<html><body><table></table></body></html>"
        mock_get.return_value = Mock(content=mock_html)

        # Act
        result = extract_news('http://mockurl.com')

        # Assert
        expected_output = '<b>HN Top Stories:</b>\n<br>--------------------------------------------------<br>'
        self.assertEqual(result, expected_output)

    @patch('webscrapper.requests.get')
    def test_invalid_url_or_network_issues(self, mock_get):
        # Arrange
        mock_get.side_effect = requests.exceptions.RequestException

        # Act & Assert
        with self.assertRaises(requests.exceptions.RequestException):
            extract_news('http://invalidurl.com')

    @patch('webscrapper.requests.get')
    def test_correct_html_parsing(self, mock_get):
        # Arrange
        mock_html = """
        <html>
            <body>
                <table>
                    <tr><td class="title" valign=""><a href="link1">News Story 1</a></td></tr>
                    <tr><td class="title" valign=""><a href="link2">News Story 2</a></td></tr>
                </table>
            </body>
        </html>
        """
        mock_get.return_value = Mock(content=mock_html)

        # Act
        result = extract_news('http://mockurl.com')

        # Assert
        expected_output = '<b>HN Top Stories:</b>\n<br>--------------------------------------------------<br>1 :: News Story 1\n<br>2 :: News Story 2\n<br>'
        self.assertEqual(result, expected_output)

